runtestsh.body:
#!/bin/sh
# Kotl job template. Put your commands in main().
main() {
  /root/my_app
}

# --- keep below: Kotl reads this line, then the system powers off ---
main; rc=$?
if [ $rc -eq 0 ]; then echo "KOTL RESULT: PASS"; else echo "KOTL RESULT: FAIL ($rc)"; fi

expectscript.body:
#!/usr/bin/expect -f
# Kotl runs this with the job's console attached.
set timeout 600
expect {
  "login:" { send "root\r" }
  timeout  { exit 2 }
}
expect "# "
send "/root/my_test\r"
expect {
  "PASS"  { set rc 0 }
  "FAIL"  { set rc 1 }
  timeout { exit 2 }
}
send "poweroff\r"
exit $rc

epilog.body:
#!/bin/sh
# Run by Slurm as root after each job. Safe to run twice.
exec runuser -u kotl -- /opt/kotl/launch end "$SLURM_JOB_ID"
